solution.solution.cpp:
#include <cstdint>

struct Wasteful
{
    char tag{};
    double value{};
    char flag{};
    std::int32_t count{};
    char code{};
    std::int16_t level{};
};

struct Compact
{
    double value{};
    std::int32_t count{};
    std::int16_t level{};
    char tag{};
    char flag{};
    char code{};
};

unitTests:
template <typename T> concept HasAllMembers = requires(T t) {
    { t.tag } -> std::same_as<char&>; { t.flag } -> std::same_as<char&>; { t.code } -> std::same_as<char&>;
    { t.value } -> std::same_as<double&>; { t.count } -> std::same_as<std::int32_t&>; { t.level } -> std::same_as<std::int16_t&>;
};
static_assert(sizeof(Wasteful) == 32, "the starting struct should be left as it is");
static_assert(HasAllMembers<Compact>, "Compact needs the same six members with the same types");
static_assert(sizeof(Compact) == 24, "reorder the members so the struct takes 24 bytes");

TEST("the data still fits") { Compact c{}; c.value = 1.5; c.count = 100000; c.level = 300; c.tag = 'a'; c.flag = 'b'; c.code = 'c'; CHECK_NEAR(c.value, 1.5, 1e-12); CHECK_EQ(c.count, 100000); CHECK_EQ(c.level, 300); CHECK_EQ(c.code, 'c'); }

